package order

import "gorm.io/gorm"

type Order struct {
  ID     uint
  UserID uint
  Items  []Item
}

type Item struct {
  ID      uint
  OrderID uint
  Name    string
  Status  string
}

func ListByUser(db *gorm.DB, userID uint) ([]Order, error) {
  var orders []Order
  if err := db.Where("user_id = ?", userID).Find(&orders).Error; err != nil {
    return nil, err
  }
  for i := range orders {
    if err := db.Where("order_id = ?", orders[i].ID).Find(&orders[i].Items).Error; err != nil {
      return nil, err
    }
  }
  return orders, nil
}

